(function(){"use strict";var pill=document.querySelector(".pill");if(!pill)return;var reduce=window.matchMedia&&window.matchMedia("(prefers-reduced-motion: reduce)").matches;var busy=false,last=0;function fire(force){var now=Date.now();if(busy||force!==true&&now-last<450)return;last=now;if(window.everaSound)window.everaSound.zap();if(reduce)return;busy=true;pill.classList.remove("is-zap");void pill.offsetWidth;pill.classList.add("is-zap");setTimeout(function(){pill.classList.remove("is-zap");busy=false},280)}pill.addEventListener("pointerenter",function(e){if(e.pointerType==="mouse")fire()});pill.addEventListener("pointerdown",function(){fire()});window.everaZap=fire})();
